def fix_namespace_prefix_w(content):
    """
    Convert text that defaults to 'w:st="' to 'w-st="'
    """
    """
    Convert text that defaults to 'w:st="' to 'w-st="'
    """
    if content is None:
        return content

    # Handle bytes input
    if isinstance(content, bytes):
        return content.replace(b'w:st="', b'w-st="')

    # Handle string input
    if isinstance(content, str):
        return content.replace('w:st="', 'w-st="')

    return content

