def dehydrate_time(value):
    """
    Dehydrator for `time` values.

:param value:
:type value: Time
:return:
    """
    """ Dehydrator for `time` values.

    :param value:
    :type value: Time
    :returns:
    """
    if isinstance(value, time):
        value = Time.from_native(value)
    nanoseconds = (
        (value.hour * 3600 + value.minute * 60 + value.second) * NANO_SECONDS
        + value.nanosecond
    )
    tz = value.tzinfo
    if tz is None:
        return Structure(b"t", nanoseconds)
    else:
        if isinstance(tz, timezone):
            offset = tz.utcoffset(None)
        else:
            offset = tz.utcoffset(datetime(1970, 1, 1))
        return Structure(b"T", nanoseconds, int(offset.total_seconds()))

