def _replace_url_args(url, url_args):
    """
    Replace any custom string URL items with values in args
    """
    """
    Replace any custom string URL items with values in args
    """
    if not url_args:
        return url

    # Handle both dict and list/tuple of args
    if isinstance(url_args, dict):
        # Replace named placeholders like {key} with values
        for key, value in url_args.items():
            url = url.replace('{' + str(key) + '}', str(value))
    else:
        # Handle positional args - replace {} or {0}, {1}, etc.
        if isinstance(url_args, (list, tuple)):
            for i, value in enumerate(url_args):
                # Try numbered placeholders first
                url = url.replace('{' + str(i) + '}', str(value))
            # Then replace any remaining {} placeholders in order
            for value in url_args:
                url = url.replace('{}', str(value), 1)
        else:
            # Single value - replace first {} or {0}
            url = url.replace('{}', str(url_args), 1)
            url = url.replace('{0}', str(url_args), 1)

    return url

